#!/usr/bin/env bash
# Write a non-secret environment file with the ARNs, URLs, and endpoints
# produced by the provisioning scripts.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck disable=SC1091
source "$SCRIPT_DIR/lib/common.sh"

umask 077
cat > "$ENV_FILE" <<EOF
# Generated by deploy/aws/10-outputs.sh on $(date -u +%Y-%m-%dT%H:%M:%SZ)
# Do not commit this file. It contains no secret values, only ARNs/URLs.
AWS_REGION=$AWS_REGION
ENVIRONMENT=$ENV
ACCOUNT_ID=$ACCOUNT_ID
PROJECT=$PROJECT
TENANT=$TENANT
TARGET_REPO=$TARGET_REPO
TARGET_SERVICE=$TARGET_SERVICE
TARGET_LOG_GROUP=$TARGET_LOG_GROUP
MANAGER_EMAIL=$MANAGER_EMAIL

VPC_ID=$VPC_ID
PUBLIC_SUBNET_1=$PUBLIC_SUBNET_1
PUBLIC_SUBNET_2=$PUBLIC_SUBNET_2
PRIVATE_SUBNET_1=$PRIVATE_SUBNET_1
PRIVATE_SUBNET_2=$PRIVATE_SUBNET_2
NAT_GATEWAY_ID=$NAT_GATEWAY_ID
ALB_SG=$ALB_SG
API_SG=$API_SG
WORKER_SG=$WORKER_SG
DB_SG=$DB_SG
REDIS_SG=$REDIS_SG
OLLAMA_SG=$OLLAMA_SG

ECS_CLUSTER=$ECS_CLUSTER
API_ECR_URI=$API_ECR_URI
WORKER_ECR_URI=$WORKER_ECR_URI
ALB_ARN=$ALB_ARN
ALB_DNS=$ALB_DNS
TARGET_GROUP_ARN=$TARGET_GROUP_ARN
API_BASE_URL=$API_BASE_URL
GITHUB_WEBHOOK_URL=${API_BASE_URL}/api/v1/webhooks/github

DB_IDENTIFIER=$DB_IDENTIFIER
DB_ENDPOINT=$DB_ENDPOINT
DB_URL_SECRET_ARN=$DB_URL_SECRET_ARN
REDIS_CLUSTER_ID=$REDIS_CLUSTER_ID
REDIS_ENDPOINT=$REDIS_ENDPOINT
REDIS_URL_SECRET_ARN=$REDIS_URL_SECRET_ARN

ALERTS_QUEUE_URL=$ALERTS_QUEUE_URL
ALERTS_QUEUE_ARN=$ALERTS_QUEUE_ARN
GITHUB_EVENTS_QUEUE_URL=$GITHUB_EVENTS_QUEUE_URL
GITHUB_EVENTS_QUEUE_ARN=$GITHUB_EVENTS_QUEUE_ARN
DEPLOYMENTS_QUEUE_URL=$DEPLOYMENTS_QUEUE_URL
DEPLOYMENTS_QUEUE_ARN=$DEPLOYMENTS_QUEUE_ARN

LAMBDA_FUNCTION_ARN=$LAMBDA_FUNCTION_ARN
EVENTBRIDGE_RULE_ARN=$EVENTBRIDGE_RULE_ARN
EXECUTION_ROLE_ARN=$EXECUTION_ROLE_ARN
API_TASK_ROLE_ARN=$API_TASK_ROLE_ARN
WORKER_TASK_ROLE_ARN=$WORKER_TASK_ROLE_ARN
LAMBDA_ROLE_ARN=$LAMBDA_ROLE_ARN
EOF

if [[ -n "${GITHUB_APP_SECRET_ARN:-}" ]]; then
  printf 'GITHUB_APP_SECRET_ARN=%s\n' "$GITHUB_APP_SECRET_ARN" >> "$ENV_FILE"
fi

if [[ -n "${RESEND_SECRET_ARN:-}" ]]; then
  printf 'RESEND_SECRET_ARN=%s\n' "$RESEND_SECRET_ARN" >> "$ENV_FILE"
fi

summary
log "Generated non-secret outputs: $ENV_FILE"
printf '\n'
cat "$ENV_FILE"
